#include <stdio.h>
#include <stdlib.h>

#define CUDA_LG_MAX_TEX1DFETCH_INDEX 27
#define CUDA_MAX_TEX1DFETCH_INDEX (((size_t)1<<CUDA_LG_MAX_TEX1DFETCH_INDEX)-1)
#define CUDA_MAX_TEX1DFETCH_INDEX_SIZE_T ((size_t) 1<<CUDA_LG_MAX_TEX1DFETCH_INDEX)

#define CUDA_MAX_BYTES_INT1 (((size_t) 1 << CUDA_LG_MAX_TEX1DFETCH_INDEX)*sizeof(int1))
#define CUDA_MAX_BYTES_INT2 (((size_t) 1 << CUDA_LG_MAX_TEX1DFETCH_INDEX)*sizeof(int2))
#define CUDA_MAX_BYTES_INT4 (((size_t) 1 << CUDA_LG_MAX_TEX1DFETCH_INDEX)*sizeof(int4))

#define NUM_BLOCKS 2
#define NUM_THREADS 384
#define TOTAL_THREADS NUM_BLOCKS*NUM_THREADS

__device__ int checksumGPU_array[NUM_BLOCKS*NUM_THREADS];

int
checksumGPU()
{
    int sum = 0;
    int host_checksumGPU[NUM_BLOCKS*NUM_THREADS];
    cudaError_t status;
    size_t i;

    cuda(MemcpyFromSymbol(host_checksumGPU, checksumGPU_array,
        TOTAL_THREADS*sizeof(int)));
    for ( i = 0; i < TOTAL_THREADS; i++ ) {
        sum += host_checksumGPU[i];
    }
    return sum;
}

cudaArray int4_array_0;

__global__ void tex1dfetch_kernel(size_t index)
{
    int texID = (int) (index>>CUDA_LG_MAX_TEX1DFETCH_INDEX);
    int i = (int) (index & (CUDA_MAX_TEX1DFETCH_INDEX_SIZE_T-1));
    int4 i4;

    if ( texID == 0 ) {
        cudaBindTextureToArray(tex4_0, int4_array_0);
        i4 = tex1Dfetch( tex4_0, i );
    }
    else if ( texID == 1 ) {
        // Add similar bindings and fetches for other textures
    }

    // Store result back to global memory
    int thread_id = blockIdx.x * blockDim.x + threadIdx.x;
    checksumGPU_array[thread_id] = i4.x + i4.y + i4.z + i4.w;
}

int main()
{
    // Initialize texture objects and arrays
    cudaResourceDesc resDesc;
    cudaTextureDesc texDesc;
    cudaChannelDesc channelDesc;
    cudaArray* array;

    memset(&resDesc, 0, sizeof(resDesc));
    memset(&texDesc, 0, sizeof(texDesc));
    memset(&channelDesc, 0, sizeof(channelDesc));

    resDesc.resType = cudaResourceTypeArray;
    resDesc.res.array.array = array;

    channelDesc.format = cudaChannelFormatKindSigned;
    channelDesc.fmt = cudaCreateChannelDesc<int>();

    texDesc.addressMode[0] = cudaAddressModeWrap;
    texDesc.filterMode = cudaFilterModePoint;
    texDesc.readMode = cudaReadModeElementType;
    texDesc.normalized = false;

    cudaMallocArray(&array, &channelDesc, CUDA_MAX_TEX1DFETCH_INDEX_SIZE_T, 4);

    cudaCreateTextureObject(&tex4_0, &resDesc, &texDesc, NULL);

    // Bind texture array
    cudaBindTextureToArray(tex4_0, int4_array_0);

    // Kernel launch
    tex1dfetch_kernel<<<NUM_BLOCKS, NUM_THREADS>>>(0);

    // Unbind texture array
    cudaUnbindTexture(tex4_0);

    // Cleanup
    cudaFreeArray(array);
    cudaDestroyTextureObject(tex4_0);

    return 0;
}
